from http.server import BaseHTTPRequestHandler, HTTPServer

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def respond(self, head_only):
        present = self.path == '/document'
        payload = ('stable' if present else 'missing').encode('utf-8')
        self.send_response(200 if present else 404)
        self.send_header('Content-Type', 'text/plain; charset=utf-8')
        self.send_header('Content-Length', str(len(payload)))
        self.end_headers()
        if not head_only:
            self.wfile.write(payload)

    def do_GET(self):
        self.respond(False)

    def do_HEAD(self):
        self.respond(True)

HTTPServer(('0.0.0.0', 8080), Handler).serve_forever()

import json
from http.server import BaseHTTPRequestHandler, HTTPServer

profile = {'name': 'Ada', 'role': 'reader'}

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def reply(self, status, text):
        payload = text.encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_GET(self):
        self.reply(200, json.dumps(profile, sort_keys=True, separators=(',', ':')))

    def do_PATCH(self):
        global profile
        text = self.rfile.read(int(self.headers.get('Content-Length', '0'))).decode('utf-8')
        try:
            patch = json.loads(text)
        except ValueError:
            self.reply(400, 'invalid')
            return
        if not isinstance(patch, dict):
            self.reply(400, 'invalid')
            return
        profile = patch
        self.do_GET()

HTTPServer(('0.0.0.0', 8080), Handler).serve_forever()

from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import unquote, urlsplit

items = {}

class Handler(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def key(self):
        return unquote(urlsplit(self.path).path[len('/items/'):], encoding='utf-8', errors='strict')

    def reply(self, status, text):
        payload = text.encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'text/plain; charset=utf-8')
        self.send_header('Content-Length', str(len(payload)))
        self.end_headers()
        self.wfile.write(payload)

    def do_PUT(self):
        items[self.key()] = self.rfile.read(int(self.headers.get('Content-Length', '0'))).decode('utf-8')
        self.reply(200, 'stored')

    def do_GET(self):
        key = self.key()
        self.reply(200 if key in items else 404, items.get(key, 'missing'))

HTTPServer(('0.0.0.0', 8080), Handler).serve_forever()
